import Foundation

/// Decides whether a pasteboard change may be recorded.
public enum ClipboardPrivacy {
    /// Pasteboard types that password managers and similar apps add to mark content as private.
    /// See nspasteboard.org.
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    public static func shouldCapture(
        pasteboardTypes: [String],
        source: ClipSource,
        isPaused: Bool,
        ignoredBundleIDs: Set<String>,
        isFromOwnInterface: Bool = false
    ) -> Bool {
        if isPaused { return false }
        // Text cut or copied inside this app's own fields (a search term, a board name) is
        // not something the user copied to keep.
        if isFromOwnInterface { return false }
        if let bundleID = source.bundleID, ignoredBundleIDs.contains(bundleID) { return false }
        return privateTypes.isDisjoint(with: pasteboardTypes)
    }
}

/// Whether copies are being recorded right now, for the places that say so.
public enum RecordingState: Equatable, Sendable {
    case recording
    /// Paused until the user turns recording back on.
    case paused
    case pausedUntil(Date)

    public init(isPaused: Bool, pausedUntil: Date?, now: Date) {
        if isPaused {
            self = .paused
        } else if let end = pausedUntil, end > now {
            self = .pausedUntil(end)
        } else {
            self = .recording
        }
    }

    public var isPaused: Bool {
        self != .recording
    }
}

/// How long to stop recording for.
public enum CapturePause: String, CaseIterable, Sendable {
    case tenMinutes
    case oneHour
    case threeHours
    case untilTomorrow
    /// Until the user turns recording back on.
    case untilResumed

    /// When the pause ends; nil for one without an end.
    public func end(from now: Date, calendar: Calendar) -> Date? {
        switch self {
        case .tenMinutes: now.addingTimeInterval(600)
        case .oneHour: now.addingTimeInterval(3600)
        case .threeHours: now.addingTimeInterval(3 * 3600)
        case .untilTomorrow: calendar.date(byAdding: .day, value: 1, to: calendar.startOfDay(for: now))
        case .untilResumed: nil
        }
    }
}

/// A part of the history to clear at once.
public enum ClearRange: String, CaseIterable, Sendable {
    case lastFifteenMinutes
    case lastHour
    case olderThanDay
    case olderThanWeek
    case olderThanMonth

    private var seconds: TimeInterval {
        switch self {
        case .lastFifteenMinutes: 900
        case .lastHour: 3600
        case .olderThanDay: 86_400
        case .olderThanWeek: 7 * 86_400
        case .olderThanMonth: 30 * 86_400
        }
    }

    /// True for the ranges that clear what is newer than the cutoff; the others clear what is older.
    public var clearsRecent: Bool {
        self == .lastFifteenMinutes || self == .lastHour
    }

    public func cutoff(from now: Date) -> Date {
        now.addingTimeInterval(-seconds)
    }
}

/// Recognises a copy that is a secret in itself: a key, a private key block, a card number.
/// Only the whole clip counts; a document that happens to mention a key is ordinary text.
public enum SensitiveText {
    public enum Reason: String, Equatable, Sendable {
        case secretKey
        case privateKey
        case cardNumber
    }

    /// Beginnings of keys that well-known services hand out.
    private static let keyPrefixes = [
        "sk-", "pk-", "rk-", "ghp_", "gho_", "ghu_", "ghs_", "github_pat_", "glpat-", "xoxb-", "xoxp-", "xoxa-",
        "AKIA", "ASIA", "AIza", "SG.", "hf_", "npm_", "shpat_",
    ]

    public static func reason(for text: String) -> Reason? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.hasPrefix("-----BEGIN"), trimmed.contains("PRIVATE KEY-----") {
            return .privateKey
        }
        // Everything else is a single token or a single number: no text around it.
        guard !trimmed.isEmpty, trimmed.count <= 4096 else { return nil }
        if isCardNumber(trimmed) { return .cardNumber }
        guard !trimmed.contains(where: \.isWhitespace) else { return nil }
        if keyPrefixes.contains(where: { trimmed.hasPrefix($0) }), trimmed.count >= 20 {
            return .secretKey
        }
        if isSignedToken(trimmed) { return .secretKey }
        return nil
    }

    /// Three dot-separated parts of web-safe base64, the first starting like encoded JSON.
    private static func isSignedToken(_ text: String) -> Bool {
        let parts = text.split(separator: ".", omittingEmptySubsequences: false)
        guard parts.count == 3, text.hasPrefix("eyJ"), text.count >= 40 else { return false }
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_="))
        return parts.allSatisfy { !$0.isEmpty && $0.unicodeScalars.allSatisfy(allowed.contains) }
    }

    /// 13 to 19 digits, alone or in groups split by spaces or dashes, with a correct check digit.
    private static func isCardNumber(_ text: String) -> Bool {
        guard text.allSatisfy({ $0.isNumber || $0 == " " || $0 == "-" }) else { return false }
        let digits = text.compactMap(\.wholeNumberValue)
        guard (13...19).contains(digits.count) else { return false }
        // The Luhn check: from the right, every second digit is doubled.
        var sum = 0
        for (index, digit) in digits.reversed().enumerated() {
            if index % 2 == 1 {
                let doubled = digit * 2
                sum += doubled > 9 ? doubled - 9 : doubled
            } else {
                sum += digit
            }
        }
        // A run of one repeated digit passes the check too and is never a card.
        return sum % 10 == 0 && Set(digits).count > 1
    }
}

